"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { CandidateForm } from "@/components/CandidateForm";
import { createRecord } from "@/services/api";
import { CandidateFormValues } from "@/types/candidate";

function toCreateRequest(values: CandidateFormValues) {
  return {
    full_name: values.full_name.trim(),
    email: values.email.trim(),
    phone: values.phone.trim(),
    position: values.position.trim(),
    experience_years: values.experience_years,
    linkedin_url: values.linkedin_url.trim() || undefined,
    cv_url: values.cv_url.trim() || undefined,
  };
}

export default function NewCandidatePage() {
  const router = useRouter();

  async function handleCreate(values: CandidateFormValues) {
    await createRecord(toCreateRequest(values));
    router.push("/?created=1");
    router.refresh();
  }

  return (
    <main className="mx-auto w-full max-w-4xl px-4 py-8 sm:px-6 lg:px-8">
      <div className="mb-4">
        <Link href="/" className="text-sm font-semibold text-cyan-700 hover:text-cyan-600">
          Volver al listado
        </Link>
      </div>
      <h1 className="mb-5 text-2xl font-bold text-slate-900">Registrar candidatura</h1>
      <CandidateForm submitLabel="Guardar candidatura" loadingLabel="Guardando..." onSubmit={handleCreate} />
    </main>
  );
}
