"use client";

import { FormEvent, useMemo, useState } from "react";
import { Candidate, CandidateFormValues } from "@/types/candidate";

interface CandidateFormProps {
  initialValues?: Candidate;
  submitLabel: string;
  loadingLabel: string;
  onSubmit: (values: CandidateFormValues) => Promise<void>;
}

interface FormErrors {
  full_name?: string;
  email?: string;
  phone?: string;
  position?: string;
  experience_years?: string;
}

function normalizeInitialValues(candidate?: Candidate): CandidateFormValues {
  return {
    full_name: candidate?.full_name ?? "",
    email: candidate?.email ?? "",
    phone: candidate?.phone ?? "",
    position: candidate?.position ?? "",
    experience_years: candidate?.experience_years ?? 0,
    linkedin_url: candidate?.linkedin_url ?? "",
    cv_url: candidate?.cv_url ?? "",
  };
}

export function CandidateForm({ initialValues, submitLabel, loadingLabel, onSubmit }: CandidateFormProps) {
  const [values, setValues] = useState<CandidateFormValues>(() => normalizeInitialValues(initialValues));
  const [errors, setErrors] = useState<FormErrors>({});
  const [submitError, setSubmitError] = useState<string>("");
  const [submitSuccess, setSubmitSuccess] = useState<string>("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const isEditMode = useMemo(() => Boolean(initialValues), [initialValues]);

  function validate(nextValues: CandidateFormValues): FormErrors {
    const nextErrors: FormErrors = {};

    if (nextValues.full_name.trim().length < 3) {
      nextErrors.full_name = "El nombre completo debe tener al menos 3 caracteres.";
    }

    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(nextValues.email.trim())) {
      nextErrors.email = "Ingresa un email valido.";
    }

    if (!/^\+?[\d\s-]{8,20}$/.test(nextValues.phone.trim())) {
      nextErrors.phone = "Ingresa un telefono valido con codigo de pais.";
    }

    if (nextValues.position.trim().length < 2) {
      nextErrors.position = "El puesto debe tener al menos 2 caracteres.";
    }

    if (Number.isNaN(nextValues.experience_years) || nextValues.experience_years < 0) {
      nextErrors.experience_years = "Los anos de experiencia deben ser 0 o mas.";
    }

    return nextErrors;
  }

  function updateField<Key extends keyof CandidateFormValues>(key: Key, value: CandidateFormValues[Key]) {
    setValues((prev) => ({ ...prev, [key]: value }));
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitError("");
    setSubmitSuccess("");

    const validationErrors = validate(values);
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length > 0) {
      return;
    }

    setIsSubmitting(true);

    try {
      await onSubmit(values);
      setSubmitSuccess(isEditMode ? "Candidatura actualizada correctamente." : "Candidatura creada correctamente.");
    } catch (error) {
      setSubmitError(error instanceof Error ? error.message : "No se pudo guardar la candidatura.");
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-5 rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
      <div className="grid gap-4 md:grid-cols-2">
        <div className="space-y-1">
          <label htmlFor="full_name" className="text-sm font-medium text-slate-700">
            Nombre completo *
          </label>
          <input
            id="full_name"
            name="full_name"
            value={values.full_name}
            onChange={(event) => updateField("full_name", event.target.value)}
            className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-900 focus:border-cyan-500 focus:outline-none"
          />
          {errors.full_name ? <p className="text-xs text-rose-600">{errors.full_name}</p> : null}
        </div>

        <div className="space-y-1">
          <label htmlFor="position" className="text-sm font-medium text-slate-700">
            Puesto *
          </label>
          <input
            id="position"
            name="position"
            value={values.position}
            onChange={(event) => updateField("position", event.target.value)}
            className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-900 focus:border-cyan-500 focus:outline-none"
          />
          {errors.position ? <p className="text-xs text-rose-600">{errors.position}</p> : null}
        </div>
      </div>

      <div className="grid gap-4 md:grid-cols-2">
        <div className="space-y-1">
          <label htmlFor="email" className="text-sm font-medium text-slate-700">
            Email *
          </label>
          <input
            id="email"
            name="email"
            type="email"
            value={values.email}
            onChange={(event) => updateField("email", event.target.value)}
            className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-900 focus:border-cyan-500 focus:outline-none"
          />
          {errors.email ? <p className="text-xs text-rose-600">{errors.email}</p> : null}
        </div>

        <div className="space-y-1">
          <label htmlFor="phone" className="text-sm font-medium text-slate-700">
            Telefono *
          </label>
          <input
            id="phone"
            name="phone"
            value={values.phone}
            onChange={(event) => updateField("phone", event.target.value)}
            className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-900 focus:border-cyan-500 focus:outline-none"
          />
          {errors.phone ? <p className="text-xs text-rose-600">{errors.phone}</p> : null}
        </div>
      </div>

      <div className="grid gap-4 md:grid-cols-3">
        <div className="space-y-1">
          <label htmlFor="experience_years" className="text-sm font-medium text-slate-700">
            Anos de experiencia *
          </label>
          <input
            id="experience_years"
            name="experience_years"
            type="number"
            min={0}
            value={values.experience_years}
            onChange={(event) => updateField("experience_years", Number(event.target.value))}
            className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-900 focus:border-cyan-500 focus:outline-none"
          />
          {errors.experience_years ? <p className="text-xs text-rose-600">{errors.experience_years}</p> : null}
        </div>

        <div className="space-y-1 md:col-span-2">
          <label htmlFor="linkedin_url" className="text-sm font-medium text-slate-700">
            Perfil LinkedIn
          </label>
          <input
            id="linkedin_url"
            name="linkedin_url"
            type="url"
            value={values.linkedin_url}
            onChange={(event) => updateField("linkedin_url", event.target.value)}
            className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-900 focus:border-cyan-500 focus:outline-none"
          />
        </div>
      </div>

      <div className="space-y-1">
        <label htmlFor="cv_url" className="text-sm font-medium text-slate-700">
          URL CV
        </label>
        <input
          id="cv_url"
          name="cv_url"
          type="url"
          value={values.cv_url}
          onChange={(event) => updateField("cv_url", event.target.value)}
          className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-900 focus:border-cyan-500 focus:outline-none"
        />
      </div>

      {submitSuccess ? <p className="rounded-lg bg-emerald-50 px-3 py-2 text-sm text-emerald-700">{submitSuccess}</p> : null}
      {submitError ? <p className="rounded-lg bg-rose-50 px-3 py-2 text-sm text-rose-700">{submitError}</p> : null}

      <button
        type="submit"
        disabled={isSubmitting}
        className="rounded-lg bg-cyan-600 px-4 py-2 text-sm font-semibold text-white transition hover:bg-cyan-500 disabled:cursor-not-allowed disabled:opacity-60"
      >
        {isSubmitting ? loadingLabel : submitLabel}
      </button>
    </form>
  );
}
